python3 -c "
import json
data = json.load(open('/app/resources/treasury_bulletin_1980_11.json'))
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'savings' in k.lower() and 'note' in k.lower():
                print(f'Key: {path}{k}')
                print(f'Value: {v}')
            search(v, path + k + '.')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, path + f'[{i}].')
search(data)
